import stylesText from './food-editor.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { showModalFresh } from '../../../../utils/dialog.js';
import { formatMacro } from '../../../../utils/format-macro.js';
import { dispatchAndSettle, whileBusy } from '../../../../utils/in-flight.js';
import { unitLabel } from '../../../../utils/line-view.js';
import { FOOD_BASE_UNITS, type FoodBaseUnit, type FoodItem, type FoodItemBarcode, type NewFoodItem } from '@motivation/shared';
import {
    HEALTH_EVENTS,
    createFoodEditorArchiveEvent,
    createFoodEditorBarcodeAddEvent,
    createFoodEditorBarcodeRemoveEvent,
    createFoodEditorDeleteEvent,
    createFoodEditorSaveEvent,
} from '../../health-events.js';
import '../../photo-controls/photo-controls.component.js';
import '../provenance-badge/provenance-badge.component.js';
import type { PhotoControls } from '../../photo-controls/photo-controls.component.js';

const styles = cssStyleSheet(stylesText);

export const FOOD_EDITOR_MODES = ['edit', 'new', 'label-draft', 'estimate-draft'] as const;
export type FoodEditorMode = typeof FOOD_EDITOR_MODES[number];

/** The per-base nutrients the editor takes, in the order shown. */
const NUTRIENTS = [
    ['calories_per_base', 'kcal'],
    ['protein_g_per_base', 'Protein g'],
    ['carbs_g_per_base', 'Carbs g'],
    ['fat_g_per_base', 'Fat g'],
    ['fiber_g_per_base', 'Fiber g'],
    ['sugar_g_per_base', 'Sugar g'],
    ['sodium_mg_per_base', 'Sodium mg'],
] as const;
type NutrientField = typeof NUTRIENTS[number][0];

const UNIT_NAMES: Record<FoodBaseUnit, string> = { g: 'grams', ml: 'millilitres', piece: 'pieces' };
const SAVE_LABELS: Record<FoodEditorMode, string> = { edit: 'Save', new: 'Create food', 'label-draft': 'Use these values', 'estimate-draft': 'Use these values' };

const template = document.createElement('template');
template.innerHTML = `
    <section class="card photo-card">
        <provenance-badge hidden></provenance-badge>
        <photo-controls scope="food"></photo-controls>
    </section>
    <section class="card grid">
        <label class="field wide"><span class="label">Name</span><input class="name" autocomplete="off" required></label>
        <label class="field"><span class="label">Brand</span><input class="brand" autocomplete="off"></label>
        <label class="field"><span class="label">Unit</span><select class="unit">
            ${FOOD_BASE_UNITS.map((u) => `<option value="${u}">${UNIT_NAMES[u]}</option>`).join('')}
        </select></label>
    </section>
    <section class="card">
        <div class="per">
            <h2 class="h2">Nutrition per</h2>
            <input class="base-amount" inputmode="decimal" aria-label="Nutrition per amount">
            <span class="base-unit"></span>
        </div>
        <div class="nutrients">
            ${NUTRIENTS.map(([field, label]) => `
                <label class="field"><span class="label">${label}</span>
                    <input data-nutrient="${field}" inputmode="decimal" autocomplete="off"></label>`).join('')}
        </div>
        <p class="unread" hidden></p>
    </section>
    <section class="card">
        <h2 class="h2">Usual portion</h2>
        <label class="portion-row"><input class="portion" inputmode="decimal" aria-label="Usual portion" placeholder="none"><span class="portion-unit"></span></label>
        <p class="portion-kcal"></p>
    </section>
    <section class="card barcodes" hidden>
        <h2 class="h2">Barcodes</h2>
        <div class="chips"></div>
        <form class="add-barcode"><input class="new-barcode" inputmode="numeric" aria-label="Add a barcode" placeholder="Add a barcode"><button type="submit">Add</button></form>
    </section>
    <p class="error" role="alert" hidden></p>
    <div class="actions"><button type="button" class="save"></button></div>
    <section class="danger" hidden>
        <div class="actions">
            <button type="button" class="archive"></button>
            <button type="button" class="delete">Delete</button>
        </div>
        <p class="hint"></p>
    </section>
    <dialog class="confirm">
        <h2 class="h2 confirm-title"></h2>
        <p class="confirm-meals"></p>
        <p class="confirm-logs">Logged lines keep their nutrition and name, without the link. To keep the link, archive it instead.</p>
        <div class="actions">
            <button type="button" class="confirm-cancel">Cancel</button>
            <button type="button" class="confirm-delete">Delete</button>
        </div>
    </dialog>
`;

/**
 * Story 423 (418 Shape) — one food in full: photo, name, brand, unit, nutrition per its base, the
 * usual portion, and — for a food that exists — its barcodes, Archive and Delete (418 #5). `mode`
 * is `edit`, `new`, or the draft a label read (`label-draft`) or an estimate (`estimate-draft`)
 * proposes; a draft shows where it came from. It writes nothing: Save emits
 * `health:food-editor-save` with the food as a `NewFoodItem`, and the rest their own events, each
 * answered through `respondWith` (story 371). Delete asks first — `confirmDelete()` is the
 * screen's, since only it can say which meals the delete touches.
 */
export class FoodEditor extends HTMLElement {
    static get observedAttributes() { return ['mode', 'provenance']; }

    private foodValue: (NewFoodItem & { id?: string }) | null = null;
    private imagePath: string | null = null;
    /** Picked or removed here since the food was set. */
    private photoTouched = false;
    private archived = false;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        customElements.upgrade(shadow);

        // The photo is part of the form: held until Save, like every other field.
        const photo = this.photo;
        photo.addEventListener(HEALTH_EVENTS.PHOTO_PICKED, (e) => { e.stopPropagation(); this.imagePath = e.detail.image_path; this.photoTouched = true; });
        photo.addEventListener(HEALTH_EVENTS.PHOTO_REMOVED, (e) => { e.stopPropagation(); this.imagePath = null; this.photoTouched = true; });
        photo.addEventListener(HEALTH_EVENTS.PHOTO_LANDED, (e) => { this.imagePath = e.detail.image_path; });

        for (const input of [this.q<HTMLInputElement>('.base-amount'), this.q<HTMLInputElement>('.portion'), this.q<HTMLInputElement>('[data-nutrient="calories_per_base"]')]) {
            input.addEventListener('input', () => this.renderPortionKcal());
        }
        this.q<HTMLSelectElement>('.unit').addEventListener('change', () => this.renderUnit());

        const save = this.q<HTMLButtonElement>('.save');
        save.addEventListener('click', () => void whileBusy(save, () => this.save()));
        const archive = this.q<HTMLButtonElement>('.archive');
        archive.addEventListener('click', () => void whileBusy(archive, () => dispatchAndSettle(this, createFoodEditorArchiveEvent({ archived: !this.archived }))));
        const del = this.q<HTMLButtonElement>('.delete');
        del.addEventListener('click', () => void whileBusy(del, () => dispatchAndSettle(this, createFoodEditorDeleteEvent())));

        this.q<HTMLFormElement>('.add-barcode').addEventListener('submit', (e) => {
            e.preventDefault();
            const input = this.q<HTMLInputElement>('.new-barcode');
            const barcode = input.value.replace(/[^0-9]/g, '');
            if (!barcode) return;
            void dispatchAndSettle(this, createFoodEditorBarcodeAddEvent({ barcode })).then(() => { input.value = ''; });
        });
        this.q('.chips').addEventListener('click', (e) => {
            const button = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-barcode]');
            if (button) void whileBusy(button, () => dispatchAndSettle(this, createFoodEditorBarcodeRemoveEvent({ barcode: button.dataset.barcode! })));
        });
    }

    get mode(): FoodEditorMode {
        const m = this.getAttribute('mode');
        return (FOOD_EDITOR_MODES as readonly string[]).includes(m ?? '') ? m as FoodEditorMode : 'edit';
    }

    /** The food to edit: a library row, or a `NewFoodItem` a draft or "+ New food" starts from. */
    set food(value: FoodItem | (NewFoodItem & { id?: string })) {
        this.foodValue = value;
        this.imagePath = value.image_path ?? null;
        this.photoTouched = false;
        this.archived = 'archived_at' in value && Boolean(value.archived_at);
        this.fill(value);
        this.render();
    }

    /** Its barcodes (edit mode). */
    set barcodes(list: FoodItemBarcode[]) {
        const chips = this.q('.chips');
        chips.replaceChildren(...list.map((b) => {
            const chip = document.createElement('span');
            chip.className = 'chip';
            chip.dataset.kind = b.kind;
            const code = document.createElement('span');
            code.textContent = b.barcode;
            const remove = document.createElement('button');
            remove.type = 'button';
            remove.dataset.barcode = b.barcode;
            remove.setAttribute('aria-label', `Remove barcode ${b.barcode}`);
            remove.textContent = '×';
            chip.append(code, remove);
            return chip;
        }));
        if (list.length === 0) {
            const none = document.createElement('span');
            none.className = 'none';
            none.textContent = 'No barcode yet.';
            chips.replaceChildren(none);
        }
    }

    /** A label read's fields it could not read (story 338) — named, so the gaps are filled by hand. */
    set unread(labels: string[]) {
        const p = this.q('.unread');
        p.hidden = labels.length === 0;
        p.textContent = labels.length === 0 ? '' : `Not read from the label: ${labels.join(', ')}. Fill them in or leave them unknown.`;
    }

    /** Ask before a delete, naming what it touches (418 #5, #17). */
    confirmDelete(meals: Array<{ name: string; deleted_with_food: boolean }>): Promise<boolean> {
        const dialog = this.q<HTMLDialogElement>('.confirm');
        const name = this.foodValue?.display_name ?? 'this food';
        this.q('.confirm-title').textContent = `Delete ${name}?`;
        const kept = meals.filter((m) => !m.deleted_with_food).map((m) => m.name);
        const gone = meals.filter((m) => m.deleted_with_food).map((m) => m.name);
        const parts: string[] = [];
        if (kept.length > 0) parts.push(`It is removed from ${kept.length === 1 ? '1 meal' : `${kept.length} meals`}: ${kept.join(', ')}.`);
        if (gone.length > 0) parts.push(`${gone.join(', ')} ${gone.length === 1 ? 'has' : 'have'} no other ingredient and ${gone.length === 1 ? 'is' : 'are'} deleted with it.`);
        this.q('.confirm-meals').textContent = parts.length > 0 ? parts.join(' ') : 'No meal uses it.';
        return new Promise((resolve) => {
            const done = (answer: boolean) => {
                cancel.removeEventListener('click', no);
                confirm.removeEventListener('click', yes);
                dialog.removeEventListener('cancel', no);
                dialog.close();
                resolve(answer);
            };
            const no = () => done(false);
            const yes = () => done(true);
            const cancel = this.q<HTMLButtonElement>('.confirm-cancel');
            const confirm = this.q<HTMLButtonElement>('.confirm-delete');
            cancel.addEventListener('click', no);
            confirm.addEventListener('click', yes);
            dialog.addEventListener('cancel', no);
            showModalFresh(dialog);
        });
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private q<T extends Element = HTMLElement>(sel: string): T {
        return this.shadowRoot!.querySelector(sel) as T;
    }

    private get photo(): PhotoControls {
        return this.q<PhotoControls>('photo-controls');
    }

    private fill(food: NewFoodItem & { id?: string }): void {
        this.q<HTMLInputElement>('.name').value = food.display_name;
        this.q<HTMLInputElement>('.brand').value = food.brand ?? '';
        this.q<HTMLSelectElement>('.unit').value = food.base_unit;
        this.q<HTMLInputElement>('.base-amount').value = formatMacro(food.base_amount);
        for (const [field] of NUTRIENTS) {
            const v = food[field];
            this.q<HTMLInputElement>(`[data-nutrient="${field}"]`).value = v === null || v === undefined ? '' : formatMacro(v);
        }
        const portion = food.default_serving_amount;
        this.q<HTMLInputElement>('.portion').value = portion === null || portion === undefined ? '' : formatMacro(portion);
        this.photo.show({ localRef: food.id ?? null, path: this.imagePath, alt: food.display_name, editable: true });
        this.renderUnit();
    }

    private renderUnit(): void {
        const unit = unitLabel(this.q<HTMLSelectElement>('.unit').value as FoodBaseUnit);
        this.q('.base-unit').textContent = unit;
        this.q('.portion-unit').textContent = unit;
        this.renderPortionKcal();
    }

    private renderPortionKcal(): void {
        const base = parseNumber(this.q<HTMLInputElement>('.base-amount').value);
        const kcal = parseNumber(this.q<HTMLInputElement>('[data-nutrient="calories_per_base"]').value);
        const portion = parseNumber(this.q<HTMLInputElement>('.portion').value);
        const line = this.q('.portion-kcal');
        line.textContent = portion && base && kcal !== null && kcal !== undefined
            ? `${formatMacro((kcal * portion) / base)} kcal per portion · filled in when you log it`
            : 'Filled in when you log it; without one, a log starts at the base amount.';
    }

    private render(): void {
        const mode = this.mode;
        const existing = mode === 'edit';
        this.q('.save').textContent = SAVE_LABELS[mode];
        this.q('.barcodes').hidden = !existing;
        this.q('.danger').hidden = !existing;
        this.q('.archive').textContent = this.archived ? 'Unarchive' : 'Archive';
        this.q('.hint').textContent = `${this.archived ? 'Unarchive puts it back in search.' : 'Archive hides it from search; logs and meals keep using it.'} Delete removes it for good: logged lines keep their own values but lose the link.`;
        const badge = this.q('provenance-badge');
        // An estimate's food may be an Open Food Facts product it matched: `provenance` says so.
        const kind = mode === 'label-draft' ? 'label' : mode === 'estimate-draft' ? (this.getAttribute('provenance') ?? 'ai') : null;
        badge.hidden = kind === null;
        if (kind) badge.setAttribute('kind', kind);
    }

    private async save(): Promise<void> {
        const error = this.q('.error');
        const problems: string[] = [];
        const name = this.q<HTMLInputElement>('.name').value.trim();
        if (!name) problems.push('Give it a name.');
        const baseAmount = parseNumber(this.q<HTMLInputElement>('.base-amount').value);
        if (!baseAmount) problems.push('The amount the nutrition is per must be above 0.');
        const nutrients: Partial<Record<NutrientField, number | null>> = {};
        const bad: string[] = [];
        for (const [field, label] of NUTRIENTS) {
            const v = parseNumber(this.q<HTMLInputElement>(`[data-nutrient="${field}"]`).value);
            if (v === undefined) bad.push(label);
            else nutrients[field] = v;
        }
        if (bad.length > 0) problems.push(`Not a number ≥ 0: ${bad.join(', ')}.`);
        const portion = parseNumber(this.q<HTMLInputElement>('.portion').value);
        if (portion === undefined || portion === 0) problems.push('The usual portion must be above 0, or empty.');
        if (problems.length > 0 || !this.foodValue || !baseAmount || portion === undefined) {
            error.textContent = problems.join(' ');
            error.hidden = false;
            return;
        }
        error.hidden = true;
        const brand = this.q<HTMLInputElement>('.brand').value.trim();
        const { id, image_path: _shown, ...base } = this.foodValue;
        const food: NewFoodItem = {
            ...stripRow(base),
            canonical_name: name,
            display_name: name,
            brand: brand || null,
            base_unit: this.q<HTMLSelectElement>('.unit').value as FoodBaseUnit,
            base_amount: baseAmount,
            ...nutrients,
            default_serving_amount: portion,
            // A food that exists sends its photo only when it was changed here: a pick queued
            // offline lands on the row by itself (story 362), and a Save meanwhile must not undo it.
            ...(id === undefined || this.photoTouched ? { image_path: this.imagePath } : {}),
        };
        return dispatchAndSettle(this, createFoodEditorSaveEvent({ food }));
    }
}

/** A library row's own bookkeeping is not part of what Save sends. */
function stripRow(food: NewFoodItem | FoodItem): NewFoodItem {
    const { created_at: _c, updated_at: _u, use_count: _n, last_used_at: _l, ...rest } = food as FoodItem;
    return rest as NewFoodItem;
}

/** A number ≥ 0 as typed; empty is unknown (null); anything else undefined (invalid). */
function parseNumber(text: string): number | null | undefined {
    const t = text.trim().replace(',', '.');
    if (t === '') return null;
    const n = Number(t);
    return Number.isFinite(n) && n >= 0 ? n : undefined;
}

if (!customElements.get('food-editor')) {
    customElements.define('food-editor', FoodEditor);
}
